partitions.content:
[
  {
    "description": "Find the most relevant semantic cards for a coding task.",
    "inputSchema": {
      "additionalProperties": false,
      "properties": {
        "task": {
          "description": "Task language to search for.",
          "minLength": 1,
          "type": "string"
        },
        "top": {
          "default": 5,
          "description": "Maximum results.",
          "maximum": 100,
          "minimum": 1,
          "type": "integer"
        }
      },
      "required": [
        "task"
      ],
      "type": "object"
    },
    "name": "llmnav_query",
    "schemaVersion": 1
  },
  {
    "description": "Resolve one local or qualified workspace semantic ID.",
    "inputSchema": {
      "additionalProperties": false,
      "properties": {
        "id": {
          "description": "Semantic ID or repository-qualified semantic ID.",
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "id"
      ],
      "type": "object"
    },
    "name": "llmnav_show",
    "schemaVersion": 1
  },
  {
    "description": "Build bounded semantic and graph context around one ID.",
    "inputSchema": {
      "additionalProperties": false,
      "properties": {
        "budget": {
          "default": 2500,
          "description": "Approximate token budget.",
          "maximum": 100000,
          "minimum": 128,
          "type": "integer"
        },
        "depth": {
          "default": 1,
          "description": "Maximum graph traversal depth.",
          "maximum": 8,
          "minimum": 0,
          "type": "integer"
        },
        "id": {
          "description": "Semantic ID or repository-qualified semantic ID.",
          "minLength": 1,
          "type": "string"
        },
        "maxEdges": {
          "default": 24,
          "description": "Maximum graph edges to inspect and pack.",
          "maximum": 1000,
          "minimum": 0,
          "type": "integer"
        }
      },
      "required": [
        "id"
      ],
      "type": "object"
    },
    "name": "llmnav_context",
    "schemaVersion": 1
  },
  {
    "description": "Validate semantic cards and configured graph inputs without mutation.",
    "inputSchema": {
      "additionalProperties": false,
      "properties": {
        "paths": {
          "default": [],
          "description": "Optional repository-relative paths to validate.",
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "type": "array"
        }
      },
      "required": [],
      "type": "object"
    },
    "name": "llmnav_check",
    "schemaVersion": 1
  }
]
